-- dev_033_open_box_safety: DEVELOPMENT MIGRATION for shipbay-nexus-dev (gdoaonsasbsperqjuurm) ONLY. NOT APPLIED.
-- Generated by supabase/dev/pending/build.sh from supabase/candidates/20261205_wms_open_box_safety.sql; do not edit by hand.
-- It replaces wms_open_box and adds wms_open_box_correct and the internal _wms_open_box_do. No table, row, pallet, carton,
-- unit label, stock entry or journal entry is touched. No DROP. Needs dev_032.
-- Apply as one migration (one transaction). Afterwards every function body must match the candidate (md5 of prosrc).

-- ===== candidate 20261205 =====
-- Open-box stock safety. CANDIDATE: tested on the local synthetic database only, applied nowhere.
-- Needs 20261127_wms_waves, 20261130_wms_nexus_putaway, 20261203_wms_inventory_workflow and 20261204_wms_pallet_stock_safety.
-- Derek's request, 2026-11-23 2:06 AM.
--
-- What "Found an open box" does today (wms_open_box): marks the carton opened and makes one unit row per loose unit on the
-- open-box shelf. On a pallet that is not put away yet that posts nothing, which is right: the count is taken at receiving. On a
-- pallet that IS put away the stock function re-posts at once: the carton's units come off the pallet's position and the number
-- typed goes onto the shelf. Any floor login, any number from 1 to 500, no checks. So:
--   1. Stock is created or lost: a carton of 10 opened as 25 adds 15 units; opened as 4 loses 6. No reason, no record of why.
--   2. A no-carton-count (NCC) carton keeps its units at the position AND gets the typed number on the shelf: created from nothing.
--   3. A heavily picked pallet: taking a carton's 10 from a position that holds 5 leaves it at minus 5.
--   4. A wave has a pick planned at the position: the carton's units are taken from under it.
--   5. While a Nexus request is waiting or out of sync the stock moves under a movement that is not settled.
--   6. A pallet that left the floor: the carton changes and the ledger does not, so they disagree from then on.
--   7. The ledger shows it as a generic 'adjust' at the position, a second 'receive' for the pallet on the shelf, and then one
--      'adjust' of +1 for every further unit.
--
-- The rule, with the existing function keeping its name and arguments:
--   wms_open_box (any floor login, as today)
--     - before put-away: exactly what it did (the count found in the box is entered; nothing is posted until put-away);
--     - on a put-away pallet: the number must equal the carton's count on file, so what leaves the position is exactly what
--       arrives on the shelf. It is recorded as one transfer pair that nets to zero, naming the carton, both places and who.
--   wms_open_box_correct (ShipBay admin or staff, reason required)
--     - a put-away carton that really holds a different number: the units found move as a transfer pair, and the difference is
--       one 'adjust' row carrying the reason, with an activity-log entry (carton, on file, found, difference, reason, who).
--   Both refuse, with nothing changed: an NCC carton; a pallet with a Nexus request that is not settled; a pallet off the shared
--   floor or departed; a shared Nexus position as the shelf; and any result that would leave the pallet's position below what
--   waves have planned there (so never below zero) or the pallet holding less than was picked from it plus what is planned.
-- Nothing else changed: the stock function, the triggers, unit labels and their numbering, the shelf default (section "open box").

create or replace function public._wms_open_box_do(p_carton_code text, p_units integer, p_location uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path to 'public' as $$
declare c wms_cartons; p wms_pallets; l locations; o wms_nexus_ops; v_who text; v_sku uuid; v_skuname text; v_from text; v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_correct boolean := p_reason is not null; v_stock boolean; v_before uuid[]; v_file int; v_move int; v_diff int; v_np int; v_ns int; v_picked int; v_planned int; x record;
begin
  if not is_wms_staff() then raise exception 'This login cannot open a box.'; end if;
  if v_correct and not wms_nexus_admin() then raise exception 'Only ShipBay admin or staff can open a box with a count that differs from the carton''s.'; end if;
  if v_correct and (v_reason is null or length(v_reason) < 4) then raise exception 'Say why the count differs.'; end if;
  if p_units is null or p_units < 1 or p_units > 500 then raise exception 'Say how many units are in the box (1 to 500).'; end if;
  select * into c from wms_cartons where code = upper(trim(p_carton_code)) for update;
  if c.id is null then raise exception '% is not a carton label on file.', upper(trim(p_carton_code)); end if;
  select * into p from wms_pallets where id = c.pallet_id for update;   -- the same row lock every Nexus request takes first
  if p.status = 'void' then raise exception '% was voided.', p.psku; end if;
  if c.open_box_at is not null then raise exception 'Carton % of % is already an open box with % units.', c.seq, p.psku, c.open_units; end if;
  if p_location is not null then select * into l from locations where id = p_location and active;
  else select * into l from locations where active and lower(zone) = 'open box' order by code limit 1; end if;
  if l.id is null then raise exception 'There is no open-box shelf set up.'; end if;

  -- the safety rules
  if c.cle then raise exception 'Carton % of % has no carton count (NCC): its units are counted on the pallet, so it cannot be opened into unit labels.', c.seq, p.psku; end if;
  if coalesce(l.shared, false) then raise exception '% is a shared Nexus position. Loose units go on a ShipBay shelf.', l.code; end if;
  if l.id = p.location_id then raise exception '% is where the pallet stands. Loose units go on a shelf.', l.code; end if;
  select * into o from wms_nexus_ops where pallet_id = p.id and state in ('pending', 'out_of_sync') order by (state = 'out_of_sync') desc, created_at limit 1;
  if o.id is not null then
    if o.state = 'out_of_sync' then raise exception 'No box of % can be opened yet: Nexus accepted % and ShipBay has not recorded it. An admin settles that under Put away first.', p.psku, coalesce(o.to_code, o.from_code); end if;
    raise exception 'No box of % can be opened yet: it has a request for % that Nexus has not answered. Finish that one first.', p.psku, coalesce(o.to_code, o.from_code);
  end if;
  if p.status = 'departed' then raise exception '% has left the building. Its cartons stay as they are.', p.psku; end if;
  if p.status = 'off_floor' then raise exception '% is off the shared floor. Put it away again before opening a box.', p.psku; end if;
  v_stock := p.status = 'stored' and p.location_id is not null;   -- put away: opening the box moves stock now
  v_file := c.units_per_carton; v_sku := coalesce(c.sku_id, p.sku_id);
  if v_correct and not (v_stock and v_file is not null and p_units <> v_file) then
    raise exception 'A correction is only for a put-away carton whose count on file (%) differs from what is in it. Open this one the usual way.', coalesce(v_file::text, 'none');
  end if;
  if v_stock and not v_correct and v_file is not null and p_units <> v_file then
    raise exception 'Carton % of % holds % on file, not %. Opening it with a different count changes stock: a ShipBay admin or staff login does that, with a reason.', c.seq, p.psku, v_file, p_units;
  end if;

  select coalesce(full_name, email) into v_who from profiles where id = auth.uid();
  select coalesce(array_agg(m.id), '{}') into v_before from inventory_moves m where m.ref_type = 'wms_pallet' and m.ref_id = p.id;
  update wms_cartons set open_box_at = now(), open_units = p_units, open_by_name = v_who,
         scanned_at = coalesce(scanned_at, now()), scanned_by_name = coalesce(scanned_by_name, v_who) where id = c.id;
  -- one statement for all the unit rows (it was a loop): the same rows and the same label numbers, and the stock function posts the shelf quantity once
  insert into wms_units (code, org_id, carton_id, pallet_id, sku_id, item_no, item_name, fba, location_id, created_by_name)
  select 'U' || lpad(nextval('wms_unit_seq')::text, 7, '0'), c.org_id, c.id, p.id, coalesce(c.sku_id, p.sku_id), coalesce(c.item_no, p.item_no),
         coalesce(c.item_name, case when p.mixed then null else p.item_name end, p.notes), coalesce(c.fba, p.fba, false), l.id, v_who
  from generate_series(1, p_units);

  if v_stock then
    select code into v_from from locations where id = p.location_id; select sku into v_skuname from skus where id = v_sku;
    -- what the stock function posted for this: the carton's count off the position, the units found onto the shelf. Anything else stops here.
    select count(*) filter (where m.location_id = p.location_id), count(*) filter (where m.location_id = l.id) into v_np, v_ns
      from inventory_moves m where m.ref_type = 'wms_pallet' and m.ref_id = p.id and not (m.id = any (v_before));
    if (select coalesce(sum(m.qty), 0) from inventory_moves m where m.ref_type = 'wms_pallet' and m.ref_id = p.id and not (m.id = any (v_before)) and m.location_id = p.location_id) <> -coalesce(v_file, 0)
       or (select coalesce(sum(m.qty), 0) from inventory_moves m where m.ref_type = 'wms_pallet' and m.ref_id = p.id and not (m.id = any (v_before)) and m.location_id = l.id) <> p_units
       or v_np <> (case when v_file is null or v_file = 0 then 0 else 1 end) or v_ns <> 1
       or exists (select 1 from inventory_moves m where m.ref_type = 'wms_pallet' and m.ref_id = p.id and not (m.id = any (v_before)) and m.location_id is distinct from p.location_id and m.location_id <> l.id) then
      raise exception 'Opening carton % of % did not post as expected. Nothing was changed.', c.seq, p.psku;
    end if;
    -- the result must be stock that exists
    for x in
      select coalesce(lo.code, 'no position') code,
        (select coalesce(sum(m.qty), 0)::int from inventory_moves m where m.sku_id = v_sku and m.location_id = d.id) on_books,
        (select coalesce(sum(t.qty_planned), 0)::int from wms_wave_tasks t join wms_waves w on w.id = t.wave_id where t.sku_id = v_sku and t.location_id = d.id and t.confirmed_at is null and w.status = 'picking') planned
      from (select p.location_id id union select l.id) d left join locations lo on lo.id = d.id
    loop
      if x.on_books < x.planned then
        raise exception 'Carton % of % cannot be opened now: that would leave % of % at %, and % are needed there%.', c.seq, p.psku, x.on_books, v_skuname, x.code, greatest(x.planned, 0),
          case when x.planned > 0 then ' for picks a wave has planned' else ' (units have been picked from that position; it cannot go below zero)' end;
      end if;
    end loop;
    select -coalesce(sum(m.qty), 0)::int into v_picked from inventory_moves m where m.pallet_id = p.id and m.reason = 'pick' and m.sku_id = v_sku;
    select coalesce(sum(t.qty_planned), 0)::int into v_planned from wms_wave_tasks t join wms_waves w on w.id = t.wave_id where t.pallet_id = p.id and t.sku_id = v_sku and t.confirmed_at is null and w.status = 'picking';
    if v_file is not null then
      -- on the ledger: the units that moved are one transfer pair; a difference between the count on file and the count found is one adjustment with the reason
      v_move := least(v_file, p_units); v_diff := p_units - v_file;
      update inventory_moves m set qty = -v_move, reason = 'transfer', note = left(p.psku || ' carton ' || c.seq || ' opened: ' || v_move || ' to ' || l.code, 200)
        where m.ref_type = 'wms_pallet' and m.ref_id = p.id and not (m.id = any (v_before)) and m.location_id = p.location_id;
      update inventory_moves m set qty = v_move, reason = 'transfer', note = left(p.psku || ' carton ' || c.seq || ' opened: ' || v_move || ' from ' || v_from, 200)
        where m.ref_type = 'wms_pallet' and m.ref_id = p.id and not (m.id = any (v_before)) and m.location_id = l.id;
      if v_diff <> 0 then
        insert into inventory_moves (org_id, sku_id, qty, reason, ref_type, ref_id, note, created_by, location_id)
        values (p.org_id, v_sku, v_diff, 'adjust', 'wms_pallet', p.id, left(p.psku || ' carton ' || c.seq || ' held ' || p_units || ', not ' || v_file || ': ' || v_reason, 200), auth.uid(),
          case when v_diff < 0 then p.location_id else l.id end);
        insert into wms_activity (org_id, kind, qty, ref, actor, actor_name, detail) values (p.org_id, 'open_box_corrected', abs(v_diff), p.psku, auth.uid(), v_who,
          jsonb_build_object('carton', c.seq, 'carton_code', c.code, 'on_file', v_file, 'found', p_units, 'units_change', v_diff, 'position', v_from, 'shelf', l.code, 'reason', v_reason));
      end if;
    end if;
    if (select coalesce(sum(m.qty), 0)::int from inventory_moves m where m.ref_type = 'wms_pallet' and m.ref_id = p.id and m.sku_id = v_sku) < v_picked + v_planned then
      raise exception 'Carton % of % cannot be opened with that count: the pallet would hold less of % than the % picked from it%.', c.seq, p.psku, v_skuname, v_picked,
        case when v_planned > 0 then ' plus ' || v_planned || ' a wave has planned' else '' end;
    end if;
  end if;
  return jsonb_build_object('pallet_id', p.id, 'psku', p.psku, 'seq', c.seq, 'units', p_units, 'location', l.code, 'location_id', l.id,
    'scanned', (select count(*) from wms_cartons where pallet_id = p.id and scanned_at is not null), 'total', (select count(*) from wms_cartons where pallet_id = p.id));
end $$;
revoke all on function public._wms_open_box_do(text, integer, uuid, text) from public, anon, authenticated, service_role;

create or replace function public.wms_open_box(p_carton_code text, p_units integer, p_location uuid default null) returns jsonb
language sql security definer set search_path to 'public' as $$
  select _wms_open_box_do(p_carton_code, p_units, p_location, null);
$$;
create or replace function public.wms_open_box_correct(p_carton_code text, p_units integer, p_location uuid, p_reason text) returns jsonb
language sql security definer set search_path to 'public' as $$
  select _wms_open_box_do(p_carton_code, p_units, p_location, coalesce(p_reason, ''));
$$;
revoke all on function public.wms_open_box_correct(text, integer, uuid, text) from public, anon;
grant execute on function public.wms_open_box_correct(text, integer, uuid, text) to authenticated;
